import { ApiProperty } from '@nestjs/swagger';
import { EntryNature, EntryScope } from '@prisma/client';
import { Transform } from 'class-transformer';
import {
  IsEnum,
  IsString,
  IsUUID,
  MaxLength,
  MinLength,
} from 'class-validator';

import { tidyCategoryName } from '../domain/category-name';

const CATEGORY_NAME_MAX_LENGTH = 40;

export class CreateFinancialCategoryDto {
  @ApiProperty({
    format: 'uuid',
    example: '3b8f5d2e-1c4a-4e7b-9a60-2f1d8c7e5b43',
    description:
      'Generated by the app (ADR-09). Resending the same id with the same payload returns the category already created.',
  })
  @IsUUID()
  id!: string;

  @ApiProperty({
    minLength: 1,
    maxLength: CATEGORY_NAME_MAX_LENGTH,
    example: 'Comida',
    description:
      'Trimmed, with repeated spaces collapsed into one, before it is checked and stored',
  })
  @Transform(({ value }: { value: unknown }) =>
    typeof value === 'string' ? tidyCategoryName(value) : value,
  )
  @IsString()
  @MinLength(1)
  @MaxLength(CATEGORY_NAME_MAX_LENGTH)
  name!: string;

  @ApiProperty({ enum: EntryNature, example: 'EXPENSE' })
  @IsEnum(EntryNature)
  nature!: EntryNature;

  @ApiProperty({
    enum: EntryScope,
    example: 'PERSONAL',
    description: 'Suggested scope for the entries that use this category',
  })
  @IsEnum(EntryScope)
  defaultScope!: EntryScope;
}
